package com.shop;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import com.shop.config.Database;
import com.shop.controller.*;
import com.shop.repository.*;
import com.shop.service.*;
import io.javalin.Javalin;
import io.javalin.json.JavalinJackson;

public class Main {
    public static void main(String[] args) {
        String dbUrl = System.getenv().getOrDefault("DB_URL", "jdbc:postgresql://localhost:5432/shop");
        String dbUser = System.getenv().getOrDefault("DB_USER", "postgres");
        String dbPassword = System.getenv().getOrDefault("DB_PASSWORD", "postgres");
        String translogUrl = System.getenv().getOrDefault("TRANSLOG_URL", "http://localhost:8081");
        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "8080"));

        Database database = new Database(dbUrl, dbUser, dbPassword);
        database.initialize();

        ProductRepository productRepository = new ProductRepository(database);
        CustomerRepository customerRepository = new CustomerRepository(database);
        OrderRepository orderRepository = new OrderRepository(database);
        NotificationRepository notificationRepository = new NotificationRepository(database);

        ShippingService shippingService = new ShippingService(translogUrl);
        CouponService couponService = new CouponService();
        ClubService clubService = new ClubService();
        PaymentService paymentService = new PaymentService();

        CheckoutService checkoutService = new CheckoutService(
                productRepository, orderRepository, shippingService,
                couponService, clubService, paymentService);

        OrderService orderService = new OrderService(
                database, orderRepository, productRepository,
                customerRepository, notificationRepository, checkoutService);

        CheckoutController checkoutController = new CheckoutController(checkoutService);
        OrderController orderController = new OrderController(orderService);
        ProductController productController = new ProductController(productRepository);
        CustomerController customerController = new CustomerController(customerRepository, notificationRepository);

        ObjectMapper objectMapper = new ObjectMapper()
                .registerModule(new JavaTimeModule())
                .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);

        Javalin app = Javalin.create(config -> {
            config.jsonMapper(new JavalinJackson(objectMapper, true));
        });

        app.post("/checkout/summary", checkoutController::calculateSummary);

        app.post("/orders", orderController::createOrder);
        app.get("/orders/{id}", orderController::getOrder);
        app.post("/orders/{id}/payment", orderController::processPayment);
        app.post("/orders/{id}/shipment", orderController::shipOrder);
        app.post("/orders/{id}/delivery", orderController::deliverOrder);
        app.post("/orders/{id}/cancellation", orderController::cancelOrder);

        app.get("/products/{sku}", productController::getProduct);

        app.get("/customers/{cpf}", customerController::getCustomer);
        app.get("/customers/{cpf}/notifications", customerController::getNotifications);
        app.post("/notifications/{id}/read", customerController::markNotificationAsRead);

        app.start(port);

        System.out.println("Server started on port " + port);
    }
}
package com.shop.config;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import com.shop.dto.CheckoutSummary;
import com.shop.model.OrderItem;
import com.shop.model.enums.*;
import org.postgresql.util.PGobject;

import java.math.BigDecimal;
import java.sql.*;
import java.util.ArrayList;
import java.util.List;

public class Database {
    private static final ObjectMapper objectMapper = new ObjectMapper()
            .registerModule(new JavaTimeModule());

    private final String url;
    private final String user;
    private final String password;

    public Database(String url, String user, String password) {
        this.url = url;
        this.user = user;
        this.password = password;
    }

    public Connection getConnection() throws SQLException {
        return DriverManager.getConnection(url, user, password);
    }

    public void initialize() {
        try (Connection conn = getConnection()) {
            createTables(conn);
            loadInitialCatalog(conn);
        } catch (SQLException e) {
            throw new RuntimeException("Failed to initialize database", e);
        }
    }

    private void createTables(Connection conn) throws SQLException {
        String[] sqls = {
            """
            CREATE TABLE IF NOT EXISTS products (
                sku VARCHAR(50) PRIMARY KEY,
                name VARCHAR(200) NOT NULL,
                price DECIMAL(10,2) NOT NULL,
                weight_kg DECIMAL(10,3) NOT NULL,
                stock INTEGER NOT NULL,
                discontinued BOOLEAN NOT NULL DEFAULT FALSE
            )
            """,
            """
            CREATE TABLE IF NOT EXISTS customers (
                cpf VARCHAR(11) PRIMARY KEY,
                email VARCHAR(255) NOT NULL,
                credit_balance DECIMAL(10,2) NOT NULL DEFAULT 0
            )
            """,
            """
            CREATE TABLE IF NOT EXISTS orders (
                id BIGSERIAL PRIMARY KEY,
                customer_cpf VARCHAR(11) NOT NULL,
                status VARCHAR(50) NOT NULL,
                created_at TIMESTAMP NOT NULL,
                summary JSONB NOT NULL,
                items JSONB NOT NULL,
                tracking_code VARCHAR(100),
                last_payment_transaction_id VARCHAR(100),
                FOREIGN KEY (customer_cpf) REFERENCES customers(cpf)
            )
            """,
            """
            CREATE TABLE IF NOT EXISTS notifications (
                id BIGSERIAL PRIMARY KEY,
                type VARCHAR(50) NOT NULL,
                order_id BIGINT NOT NULL,
                customer_cpf VARCHAR(11) NOT NULL,
                status VARCHAR(50) NOT NULL,
                FOREIGN KEY (order_id) REFERENCES orders(id),
                FOREIGN KEY (customer_cpf) REFERENCES customers(cpf)
            )
            """,
            """
            CREATE INDEX IF NOT EXISTS idx_orders_customer ON orders(customer_cpf)
            """,
            """
            CREATE INDEX IF NOT EXISTS idx_notifications_customer ON notifications(customer_cpf)
            """
        };

        for (String sql : sqls) {
            try (Statement stmt = conn.createStatement()) {
                stmt.execute(sql);
            }
        }
    }

    private void loadInitialCatalog(Connection conn) throws SQLException {
        String checkSql = "SELECT COUNT(*) FROM products";
        try (Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(checkSql)) {
            if (rs.next() && rs.getInt(1) > 0) {
                return;
            }
        }

        String insertSql = """
            INSERT INTO products (sku, name, price, weight_kg, stock, discontinued) VALUES
            ('CAM-001', 'Camiseta básica', 79.90, 0.30, 50, false),
            ('TEN-001', 'Tênis corrida', 249.90, 1.20, 10, false),
            ('FON-001', 'Fone sem fio', 199.90, 0.25, 5, false),
            ('MEI-001', 'Meia esportiva', 19.90, 0.10, 100, false),
            ('JAQ-001', 'Jaqueta corta-vento', 389.90, 0.80, 3, false),
            ('MOC-001', 'Mochila urbana', 159.90, 0.90, 1, false),
            ('BON-001', 'Boné aba reta', 59.90, 0.15, 0, false),
            ('REL-001', 'Relógio digital', 129.90, 0.20, 8, true)
            """;

        try (Statement stmt = conn.createStatement()) {
            stmt.execute(insertSql);
        }
    }

    public static String toJson(Object obj) {
        try {
            return objectMapper.writeValueAsString(obj);
        } catch (Exception e) {
            throw new RuntimeException("Failed to serialize to JSON", e);
        }
    }

    public static <T> T fromJson(String json, Class<T> clazz) {
        try {
            return objectMapper.readValue(json, clazz);
        } catch (Exception e) {
            throw new RuntimeException("Failed to deserialize from JSON", e);
        }
    }

    public static CheckoutSummary getSummaryFromResultSet(ResultSet rs, String columnName) throws SQLException {
        String json = rs.getString(columnName);
        return fromJson(json, CheckoutSummary.class);
    }

    public static List<OrderItem> getItemsFromResultSet(ResultSet rs, String columnName) throws SQLException {
        String json = rs.getString(columnName);
        try {
            return objectMapper.readValue(json,
                objectMapper.getTypeFactory().constructCollectionType(List.class, OrderItem.class));
        } catch (Exception e) {
            throw new SQLException("Failed to parse items", e);
        }
    }

    public static PGobject createJsonb(Object obj) throws SQLException {
        PGobject jsonb = new PGobject();
        jsonb.setType("jsonb");
        jsonb.setValue(toJson(obj));
        return jsonb;
    }
}
package com.shop.service;

import com.shop.config.Database;
import com.shop.dto.CheckoutRequest;
import com.shop.dto.CheckoutSummary;
import com.shop.exception.BusinessException;
import com.shop.model.Order;
import com.shop.model.OrderItem;
import com.shop.model.enums.NotificationType;
import com.shop.model.enums.OrderStatus;
import com.shop.repository.CustomerRepository;
import com.shop.repository.NotificationRepository;
import com.shop.repository.OrderRepository;
import com.shop.repository.ProductRepository;

import java.sql.Connection;
import java.sql.SQLException;
import java.time.Duration;
import java.time.Instant;
import java.util.HashMap;
import java.util.Map;

public class OrderService {
    private final Database database;
    private final OrderRepository orderRepository;
    private final ProductRepository productRepository;
    private final CustomerRepository customerRepository;
    private final NotificationRepository notificationRepository;
    private final CheckoutService checkoutService;

    private final Map<String, PaymentResult> paymentCache = new HashMap<>();

    private static class PaymentResult {
        boolean success;
        String errorCode;
        Order order;

        PaymentResult(boolean success, String errorCode, Order order) {
            this.success = success;
            this.errorCode = errorCode;
            this.order = order;
        }
    }

    public OrderService(Database database, OrderRepository orderRepository,
                       ProductRepository productRepository, CustomerRepository customerRepository,
                       NotificationRepository notificationRepository, CheckoutService checkoutService) {
        this.database = database;
        this.orderRepository = orderRepository;
        this.productRepository = productRepository;
        this.customerRepository = customerRepository;
        this.notificationRepository = notificationRepository;
        this.checkoutService = checkoutService;
    }

    public Order createOrder(CheckoutRequest request) {
        try (Connection conn = database.getConnection()) {
            conn.setAutoCommit(false);
            try {
                CheckoutSummary summary = checkoutService.calculateSummary(request, conn);

                customerRepository.create(conn, request.getCustomer().getCpf(), request.getCustomer().getEmail());

                Long orderId = orderRepository.create(conn, request.getCustomer().getCpf(), summary, request.getItems());

                conn.commit();

                return orderRepository.findById(orderId);
            } catch (BusinessException e) {
                conn.rollback();
                throw e;
            } catch (Exception e) {
                conn.rollback();
                throw new RuntimeException("Failed to create order", e);
            }
        } catch (SQLException e) {
            throw new RuntimeException("Database connection failed", e);
        }
    }

    public Order processPayment(Long orderId, String transactionId, Instant paidAt) {
        String cacheKey = orderId + ":" + transactionId;

        synchronized (paymentCache) {
            if (paymentCache.containsKey(cacheKey)) {
                PaymentResult cached = paymentCache.get(cacheKey);
                if (!cached.success) {
                    throw new BusinessException(cached.errorCode, 409);
                }
                return cached.order;
            }
        }

        try (Connection conn = database.getConnection()) {
            conn.setAutoCommit(false);
            try {
                Order order = orderRepository.findByIdForUpdate(conn, orderId);
                if (order == null) {
                    throw new BusinessException("ORDER_NOT_FOUND", 404);
                }

                if (order.getStatus() != OrderStatus.AWAITING_PAYMENT) {
                    throw new BusinessException("OPERATION_NOT_ALLOWED", 409);
                }

                Duration timeSinceCreation = Duration.between(order.getCreatedAt(), paidAt);
                if (timeSinceCreation.toHours() > 48) {
                    orderRepository.updateStatus(conn, orderId, OrderStatus.CANCELLED);
                    orderRepository.updatePaymentTransaction(conn, orderId, transactionId);
                    notificationRepository.create(conn, NotificationType.ORDER_CANCELLED, orderId, order.getCustomerCpf());
                    conn.commit();

                    Order cancelledOrder = orderRepository.findById(orderId);
                    synchronized (paymentCache) {
                        paymentCache.put(cacheKey, new PaymentResult(false, "ORDER_EXPIRED", cancelledOrder));
                    }
                    throw new BusinessException("ORDER_EXPIRED", 409);
                }

                try {
                    for (OrderItem item : order.getItems()) {
                        productRepository.decrementStock(conn, item.getSku(), item.getQuantity());
                    }
                } catch (SQLException e) {
                    orderRepository.updateStatus(conn, orderId, OrderStatus.CANCELLED);
                    orderRepository.updatePaymentTransaction(conn, orderId, transactionId);
                    notificationRepository.create(conn, NotificationType.ORDER_CANCELLED, orderId, order.getCustomerCpf());
                    conn.commit();

                    Order cancelledOrder = orderRepository.findById(orderId);
                    synchronized (paymentCache) {
                        paymentCache.put(cacheKey, new PaymentResult(false, "INSUFFICIENT_STOCK", cancelledOrder));
                    }
                    throw new BusinessException("INSUFFICIENT_STOCK", 409);
                }

                if (order.getSummary().getNextPurchaseCredit().compareTo(java.math.BigDecimal.ZERO) > 0) {
                    customerRepository.addCredit(conn, order.getCustomerCpf(), order.getSummary().getNextPurchaseCredit());
                }

                orderRepository.updateStatus(conn, orderId, OrderStatus.PAID);
                orderRepository.updatePaymentTransaction(conn, orderId, transactionId);

                notificationRepository.create(conn, NotificationType.PAYMENT_APPROVED, orderId, order.getCustomerCpf());

                conn.commit();

                Order paidOrder = orderRepository.findById(orderId);
                synchronized (paymentCache) {
                    paymentCache.put(cacheKey, new PaymentResult(true, null, paidOrder));
                }
                return paidOrder;

            } catch (BusinessException e) {
                conn.rollback();
                throw e;
            } catch (Exception e) {
                conn.rollback();
                throw new RuntimeException("Failed to process payment", e);
            }
        } catch (SQLException e) {
            throw new RuntimeException("Database connection failed", e);
        }
    }

    public Order shipOrder(Long orderId, String trackingCode) {
        try (Connection conn = database.getConnection()) {
            conn.setAutoCommit(false);
            try {
                Order order = orderRepository.findByIdForUpdate(conn, orderId);
                if (order == null) {
                    throw new BusinessException("ORDER_NOT_FOUND", 404);
                }

                if (order.getStatus() != OrderStatus.PAID) {
                    throw new BusinessException("OPERATION_NOT_ALLOWED", 409);
                }

                orderRepository.updateStatus(conn, orderId, OrderStatus.SHIPPED);
                orderRepository.updateTrackingCode(conn, orderId, trackingCode);

                notificationRepository.create(conn, NotificationType.ORDER_SHIPPED, orderId, order.getCustomerCpf());

                conn.commit();
                return orderRepository.findById(orderId);
            } catch (BusinessException e) {
                conn.rollback();
                throw e;
            } catch (Exception e) {
                conn.rollback();
                throw new RuntimeException("Failed to ship order", e);
            }
        } catch (SQLException e) {
            throw new RuntimeException("Database connection failed", e);
        }
    }

    public Order deliverOrder(Long orderId) {
        try (Connection conn = database.getConnection()) {
            conn.setAutoCommit(false);
            try {
                Order order = orderRepository.findByIdForUpdate(conn, orderId);
                if (order == null) {
                    throw new BusinessException("ORDER_NOT_FOUND", 404);
                }

                if (order.getStatus() != OrderStatus.SHIPPED) {
                    throw new BusinessException("OPERATION_NOT_ALLOWED", 409);
                }

                orderRepository.updateStatus(conn, orderId, OrderStatus.DELIVERED);

                conn.commit();
                return orderRepository.findById(orderId);
            } catch (BusinessException e) {
                conn.rollback();
                throw e;
            } catch (Exception e) {
                conn.rollback();
                throw new RuntimeException("Failed to deliver order", e);
            }
        } catch (SQLException e) {
            throw new RuntimeException("Database connection failed", e);
        }
    }

    public Order cancelOrder(Long orderId) {
        try (Connection conn = database.getConnection()) {
            conn.setAutoCommit(false);
            try {
                Order order = orderRepository.findByIdForUpdate(conn, orderId);
                if (order == null) {
                    throw new BusinessException("ORDER_NOT_FOUND", 404);
                }

                if (order.getStatus() == OrderStatus.SHIPPED || order.getStatus() == OrderStatus.DELIVERED) {
                    throw new BusinessException("OPERATION_NOT_ALLOWED", 409);
                }

                if (order.getStatus() == OrderStatus.CANCELLED) {
                    conn.commit();
                    return order;
                }

                if (order.getStatus() == OrderStatus.PAID) {
                    for (OrderItem item : order.getItems()) {
                        productRepository.incrementStock(conn, item.getSku(), item.getQuantity());
                    }

                    if (order.getSummary().getNextPurchaseCredit().compareTo(java.math.BigDecimal.ZERO) > 0) {
                        customerRepository.subtractCredit(conn, order.getCustomerCpf(),
                                order.getSummary().getNextPurchaseCredit());
                    }
                }

                orderRepository.updateStatus(conn, orderId, OrderStatus.CANCELLED);
                notificationRepository.create(conn, NotificationType.ORDER_CANCELLED, orderId, order.getCustomerCpf());

                conn.commit();
                return orderRepository.findById(orderId);
            } catch (BusinessException e) {
                conn.rollback();
                throw e;
            } catch (Exception e) {
                conn.rollback();
                throw new RuntimeException("Failed to cancel order", e);
            }
        } catch (SQLException e) {
            throw new RuntimeException("Database connection failed", e);
        }
    }

    public Order getOrder(Long orderId) {
        Order order = orderRepository.findById(orderId);
        if (order == null) {
            throw new BusinessException("ORDER_NOT_FOUND", 404);
        }
        return order;
    }
}

