import java.util.concurrent.*;

public class Stub {
    static volatile String body = "{\"price_cents\":3310,\"eta_hours\":41}";
    static volatile int status = 200;
    static volatile long delayMs = 0;
    static final List<String> log = Collections.synchronizedList(new ArrayList<>());
    public static void main(String[] a) throws Exception {
        HttpServer s = HttpServer.create(new InetSocketAddress(9090), 0);
        s.setExecutor(Executors.newCachedThreadPool());
        s.createContext("/v2/quote", ex -> {
            log.add(ex.getRequestURI().toString());
            try { if (delayMs > 0) Thread.sleep(delayMs); } catch (InterruptedException e) {}
            byte[] b = body.getBytes(StandardCharsets.UTF_8);
            ex.getResponseHeaders().add("Content-Type", "application/json");
            ex.sendResponseHeaders(status, b.length);
            ex.getResponseBody().write(b); ex.close();
        });
        s.createContext("/control", ex -> {
            String q = ex.getRequestURI().getQuery();
            Map<String,String> m = new HashMap<>();
            if (q != null) for (String p : q.split("&")) { String[] kv = p.split("=",2); m.put(kv[0], URLDecoder.decode(kv.length>1?kv[1]:"", StandardCharsets.UTF_8)); }
            if (m.containsKey("status")) status = Integer.parseInt(m.get("status"));
            if (m.containsKey("delay")) delayMs = Long.parseLong(m.get("delay"));
            byte[] in = ex.getRequestBody().readAllBytes();
            if (in.length > 0) body = new String(in, StandardCharsets.UTF_8);
            String out;
            if (m.containsKey("log")) { out = String.join("\n", log); log.clear(); } else out = "ok status=" + status + " delay=" + delayMs + " body=" + body;
            byte[] b = out.getBytes(StandardCharsets.UTF_8);
            ex.sendResponseHeaders(200, b.length); ex.getResponseBody().write(b); ex.close();
        });
        s.start();
        System.out.println("stub up");
    }
}
